import{_ as a,o as s,c as e,ai as d}from"./chunks/framework.iNbpOH0p.js";const T=JSON.parse('{"title":"HTTP 答案","description":"","frontmatter":{},"headers":[],"relativePath":"doc/2.Interview/2.Answer/Answer-9/11-HTTP.md","filePath":"doc/2.Interview/2.Answer/Answer-9/11-HTTP.md"}'),n={name:"doc/2.Interview/2.Answer/Answer-9/11-HTTP.md"};function r(i,t,o,l,h,p){return s(),e("div",null,[...t[0]||(t[0]=[d(`<h1 id="http-答案" tabindex="-1">HTTP 答案 <a class="header-anchor" href="#http-答案" aria-label="Permalink to “HTTP 答案”">​</a></h1><h2 id="一、http-基础" tabindex="-1">一、HTTP 基础 <a class="header-anchor" href="#一、http-基础" aria-label="Permalink to “一、HTTP 基础”">​</a></h2><h3 id="http-是什么" tabindex="-1">HTTP 是什么？ <a class="header-anchor" href="#http-是什么" aria-label="Permalink to “HTTP 是什么？”">​</a></h3><p><strong>HTTP</strong>（超文本传输协议）是客户端和服务器之间的通信协议，基于 TCP，<strong>无状态</strong>。</p><h3 id="http-报文结构" tabindex="-1">HTTP 报文结构 <a class="header-anchor" href="#http-报文结构" aria-label="Permalink to “HTTP 报文结构”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请求报文：起始行(GET /api HTTP/1.1) + 请求头(Host/User-Agent等) + 空行 + 请求体</span></span>
<span class="line"><span>响应报文：状态行(HTTP/1.1 200 OK) + 响应头 + 空行 + 响应体</span></span></code></pre></div><hr><h2 id="二、http-方法" tabindex="-1">二、HTTP 方法 <a class="header-anchor" href="#二、http-方法" aria-label="Permalink to “二、HTTP 方法”">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>语义</th><th>安全</th><th>幂等</th></tr></thead><tbody><tr><td>GET</td><td>获取</td><td>✅</td><td>✅</td></tr><tr><td>POST</td><td>创建</td><td>❌</td><td>❌</td></tr><tr><td>PUT</td><td>更新（全量）</td><td>❌</td><td>✅</td></tr><tr><td>PATCH</td><td>更新（部分）</td><td>❌</td><td>❌</td></tr><tr><td>DELETE</td><td>删除</td><td>❌</td><td>✅</td></tr><tr><td>HEAD</td><td>获取头部</td><td>✅</td><td>✅</td></tr><tr><td>OPTIONS</td><td>预检请求</td><td>✅</td><td>✅</td></tr></tbody></table><p><strong>GET vs POST</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>GET</th><th>POST</th></tr></thead><tbody><tr><td>缓存</td><td>✅</td><td>❌</td></tr><tr><td>书签</td><td>✅</td><td>❌</td></tr><tr><td>数据位置</td><td>URL(查询串）</td><td>Body</td></tr><tr><td>长度</td><td>受 URL 长度限(~2KB)</td><td>无限制</td></tr></tbody></table><hr><h2 id="三、http-状态码" tabindex="-1">三、HTTP 状态码 <a class="header-anchor" href="#三、http-状态码" aria-label="Permalink to “三、HTTP 状态码”">​</a></h2><table tabindex="0"><thead><tr><th>范围</th><th>含义</th><th>典型</th></tr></thead><tbody><tr><td>1xx</td><td>信息</td><td>101 Switching Protocols(WebSocket)</td></tr><tr><td>2xx</td><td>成功</td><td>200 OK, 201 Created, 204 No Content</td></tr><tr><td>3xx</td><td>重定向</td><td>301 永久, 302 临时, 304 Not Modified</td></tr><tr><td>4xx</td><td>客户端错误</td><td>400 Bad Request, 401 未认证, 403 禁止, 404 未找到</td></tr><tr><td>5xx</td><td>服务端错误</td><td>500 内部错误, 502 Bad Gateway, 503 不可用</td></tr></tbody></table><p><strong>301 vs 302</strong>：301 永久迁移（SEO 权重转移）；302 临时跳转</p><hr><h2 id="四、https" tabindex="-1">四、HTTPS <a class="header-anchor" href="#四、https" aria-label="Permalink to “四、HTTPS”">​</a></h2><p><strong>HTTPS = HTTP + TLS/SSL</strong>。提供：<strong>加密</strong>、<strong>完整性校验</strong>、<strong>身份认证</strong></p><p><strong>TLS 握手</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>客户端 → ServerHello(支持的加密套件) → </span></span>
<span class="line"><span>服务器 ← 证书 + 公钥 ← </span></span>
<span class="line"><span>客户端 → 用公钥加密的会话密钥 → </span></span>
<span class="line"><span>双方用会话密钥对称加密通信</span></span></code></pre></div><hr><h2 id="五、http-版本演进" tabindex="-1">五、HTTP 版本演进 <a class="header-anchor" href="#五、http-版本演进" aria-label="Permalink to “五、HTTP 版本演进”">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>特点</th></tr></thead><tbody><tr><td>HTTP/1.0</td><td>短连接，每次请求建立 TCP</td></tr><tr><td>HTTP/1.1</td><td><strong>持久连接</strong>（Keep-Alive）、管道化、Host 头</td></tr><tr><td>HTTP/2</td><td><strong>多路复用</strong>、头部压缩(HPACK)、Server Push、二进制分帧</td></tr><tr><td>HTTP/3</td><td><strong>QUIC(UDP)</strong>，0-RTT，解决队头阻塞</td></tr></tbody></table><hr><h2 id="六、缓存机制" tabindex="-1">六、缓存机制 <a class="header-anchor" href="#六、缓存机制" aria-label="Permalink to “六、缓存机制”">​</a></h2><p><strong>强缓存</strong>（不发请求）：</p><ul><li><code>Expires</code>：绝对时间（HTTP/1.0，已淘汰倾向）</li><li><code>Cache-Control: max-age=3600</code>（HTTP/1.1，<strong>推荐</strong>）</li></ul><p><strong>协商缓存</strong>（发请求带验证）：</p><ul><li><code>If-Modified-Since</code> → <code>Last-Modified</code></li><li><code>If-None-Match</code> → <code>ETag</code>（<strong>优先于</strong> Last-Modified）</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>缓存判断流程：</span></span>
<span class="line"><span>请求 → 有 Cache-Control/Expires 且未过期？→ 直接用缓存</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>没有/已过期 → 带 If-None-Match (ETag) 请求</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>服务器 304 Not Modified？→ 用缓存</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>200 → 返回新数据</span></span></code></pre></div><hr><h2 id="七、跨域-cors" tabindex="-1">七、跨域（CORS） <a class="header-anchor" href="#七、跨域-cors" aria-label="Permalink to “七、跨域（CORS）”">​</a></h2><p>同源策略：协议+域名+端口全相同。</p><p><strong>CORS 方案</strong>：</p><ul><li>简单请求：直接发，检查 <code>Access-Control-Allow-Origin</code></li><li>预检请求(OPTIONS)：非简单请求先发 OPTIONS 确认</li></ul><p><strong>其他跨域方案</strong>：</p><ul><li>JSONP（仅 GET，利用 <code>&lt;script&gt;</code> 无跨域限制）</li><li>代理（devServer.proxy / Nginx 反向代理）</li><li>postMessage</li><li>WebSocket</li></ul><hr><h2 id="八、cookie-session-token-jwt" tabindex="-1">八、Cookie / Session / Token / JWT <a class="header-anchor" href="#八、cookie-session-token-jwt" aria-label="Permalink to “八、Cookie / Session / Token / JWT”">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>存储</th><th>跨域</th><th>扩展</th></tr></thead><tbody><tr><td>Cookie</td><td>浏览器 4KB</td><td>❌(同域)</td><td>随请求发送</td></tr><tr><td>Session</td><td>服务器 + Cookie ID</td><td>❌</td><td>服务端状态</td></tr><tr><td>Token/JWT</td><td>浏览器(localStorage/Cookie)</td><td>✅</td><td><strong>无状态</strong>，适合分布式</td></tr></tbody></table><p><strong>JWT 结构</strong>：<code>Header.Payload.Signature</code>（Base64 编码三部分）</p><hr><h2 id="九、tcp-三次握手与四次挥手" tabindex="-1">九、TCP 三次握手与四次挥手 <a class="header-anchor" href="#九、tcp-三次握手与四次挥手" aria-label="Permalink to “九、TCP 三次握手与四次挥手”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>三次握手：</span></span>
<span class="line"><span>客户端 → SYN=1, seq=x → 服务器</span></span>
<span class="line"><span>客户端 ← SYN=1, ACK=1, ack=x+1, seq=y ← 服务器</span></span>
<span class="line"><span>客户端 → ACK=1, ack=y+1, seq=x+1 → 服务器</span></span>
<span class="line"><span></span></span>
<span class="line"><span>四次挥手：</span></span>
<span class="line"><span>客户端 → FIN=1 → 服务器</span></span>
<span class="line"><span>客户端 ← ACK=1 ← 服务器</span></span>
<span class="line"><span>客户端 ← FIN=1 ← 服务器</span></span>
<span class="line"><span>客户端 → ACK=1 → 服务器 → 等待 2MSL 关闭</span></span></code></pre></div><hr><h2 id="十、cdn、dns、url-解析" tabindex="-1">十、CDN、DNS、URL 解析 <a class="header-anchor" href="#十、cdn、dns、url-解析" aria-label="Permalink to “十、CDN、DNS、URL 解析”">​</a></h2><p><strong>CDN</strong>：内容分发网络，用户就近访问缓存节点。</p><p><strong>DNS 解析</strong>：域名 → IP（递归+迭代查询）。</p><p><strong>URL → 页面的完整流程</strong>：DNS → TCP → TLS(HTTPS) → HTTP 请求 → 服务器处理 → 浏览器渲染（DOM+CSSOM→Layout→Paint）。</p><hr><h2 id="十一、websocket" tabindex="-1">十一、WebSocket <a class="header-anchor" href="#十一、websocket" aria-label="Permalink to “十一、WebSocket”">​</a></h2><p>全双工通信协议，基于 TCP，用 <code>ws://</code> 或 <code>wss://</code>。HTTP 升级为 WebSocket 后保持长连接。适用场景：实时聊天、数据推送、协作编辑。</p>`,52)])])}const g=a(n,[["render",r]]);export{T as __pageData,g as default};
